:root {
  --bg: #1b1f2a;
  --card: #262c3b;
  --accent: #4fd1c5;
  --accent-dark: #2c9c92;
  --text: #eef2f7;
  --muted: #9aa6b8;
  --danger: #e26d6d;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 50% 0%, #2a3245, var(--bg));
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 17px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 18px;
  padding: 28px 24px 24px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

h1 {
  margin: 0 0 22px;
  font-size: 1.45rem;
  text-align: center;
  letter-spacing: 0.5px;
}

.settings {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 14px;
  align-items: center;
}

.settings label {
  font-size: 0.95rem;
  color: var(--muted);
}

.settings input {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: #1e2431;
  border: 2px solid #3a4356;
  border-radius: 10px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.settings input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 209, 197, 0.25);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 18px;
  border-radius: 10px;
  border: 2px solid transparent;
  background: #3a4356;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, box-shadow 0.15s;
}

.btn:hover { background: #4a5468; }
.btn:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(79, 209, 197, 0.45); }
.btn:active { transform: translateY(1px); }

.btn.primary {
  grid-column: 1 / -1;
  margin-top: 6px;
  background: var(--accent);
  color: #10201e;
}
.btn.primary:hover { background: #63e0d4; }
.btn.primary:focus-visible { box-shadow: 0 0 0 3px rgba(79, 209, 197, 0.5); }

.btn.danger { background: var(--danger); color: #2a0d0d; }
.btn.danger:hover { background: #ef8080; }
.btn.danger:focus-visible { box-shadow: 0 0 0 3px rgba(226, 109, 109, 0.5); }

.display {
  text-align: center;
  margin-top: 24px;
}

.phase {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
}

.time {
  margin: 8px 0;
  font-size: 4.5rem;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.round {
  margin: 0 0 20px;
  color: var(--muted);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.controls .btn { flex: 1; }

.status {
  margin: 18px 0 0;
  min-height: 1.5em;
  text-align: center;
  font-weight: 600;
  color: var(--accent);
}

@media (max-width: 380px) {
  .time { font-size: 3.5rem; }
  .settings { grid-template-columns: 1fr; }
}

(function () {
  'use strict';

  var form = document.getElementById('settings');
  var workInput = document.getElementById('work');
  var restInput = document.getElementById('rest');
  var roundsInput = document.getElementById('rounds');
  var display = document.getElementById('display');
  var phaseEl = document.getElementById('phase');
  var timeEl = document.getElementById('time');
  var roundEl = document.getElementById('round');
  var pauseBtn = document.getElementById('pause');
  var stopBtn = document.getElementById('stop');
  var statusEl = document.getElementById('status');

  var timer = null;
  var state = null;

  function readConfig() {
    var work = clamp(parseInt(workInput.value, 10) || 1, 1, 3600);
    var rest = clamp(parseInt(restInput.value, 10) || 1, 1, 3600);
    var rounds = clamp(parseInt(roundsInput.value, 10) || 1, 1, 99);
    return { work: work, rest: rest, rounds: rounds };
  }

  function clamp(n, min, max) {
    return Math.min(max, Math.max(min, n));
  }

  function start() {
    var cfg = readConfig();
    state = {
      work: cfg.work,
      rest: cfg.rest,
      rounds: cfg.rounds,
      round: 1,
      phase: 'work',
      remaining: cfg.work,
      paused: false
    };
    statusEl.textContent = '';
    display.hidden = false;
    pauseBtn.textContent = 'Pause';
    render();
    tickLoop();
  }

  function tickLoop() {
    clearInterval(timer);
    timer = setInterval(tick, 1000);
  }

  function tick() {
    if (!state || state.paused) return;
    state.remaining -= 1;
    if (state.remaining > 0) {
      render();
      return;
    }
    advance();
  }

  function advance() {
    if (state.phase === 'work') {
      state.phase = 'rest';
      state.remaining = state.rest;
      render();
      return;
    }
    if (state.round >= state.rounds) {
      finish();
      return;
    }
    state.round += 1;
    state.phase = 'work';
    state.remaining = state.work;
    render();
  }

  function render() {
    phaseEl.textContent = state.phase === 'work' ? 'Work' : 'Rest';
    timeEl.textContent = String(state.remaining);
    roundEl.textContent = 'Round ' + state.round + ' of ' + state.rounds;
  }

  function finish() {
    clearInterval(timer);
    timer = null;
    state = null;
    display.hidden = true;
    statusEl.textContent = 'Workout complete';
    say('Workout complete');
  }

  function togglePause() {
    if (!state) return;
    state.paused = !state.paused;
    pauseBtn.textContent = state.paused ? 'Resume' : 'Pause';
    statusEl.textContent = state.paused ? 'Paused' : '';
  }

  function stop() {
    clearInterval(timer);
    timer = null;
    state = null;
    display.hidden = true;
    statusEl.textContent = '';
  }

  function say(text) {
    if (typeof window.speechSynthesis !== 'undefined' && window.SpeechSynthesisUtterance) {
      try {
        var u = new SpeechSynthesisUtterance(text);
        window.speechSynthesis.cancel();
        window.speechSynthesis.speak(u);
      } catch (e) { /* speech unavailable */ }
    }
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    start();
  });
  pauseBtn.addEventListener('click', togglePause);
  stopBtn.addEventListener('click', stop);
})();
